def matching_changed(board,changed):
    def match(points):
        values=[board[i] for i in points]
        return bool(set(points)&changed) and values[0] in (1,2,3,4,5,6) and len(set(values))==1
    for y in range(height):
        for x in range(width):
            i=x+width*y
            if x+2<width and match([i,i+1,i+2]):return True
            if y+2<height and match([i,i+width,i+width*2]):return True
            if x+1<width and y+1<height and match([i,i+1,i+width,i+width+1]):return True
    return False
def matching_cells(board):
    cells=set()
    def add(points):
        values=[board[i] for i in points]
        if values[0] in (1,2,3,4,5,6) and len(set(values))==1:cells.update(points)
    for y in range(height):
        for x in range(width):
            i=x+width*y
            if x+2<width:add([i,i+1,i+2])
            if y+2<height:add([i,i+width,i+width*2])
            if x+1<width and y+1<height:add([i,i+1,i+width,i+width+1])
    return cells
assert not matching_changed(ids,set(range(len(ids))))
cases=[];expected=[];blocked=0;box_counts=[]
for y in range(height):
    for x in range(width):
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if not (0<=nx<width and 0<=ny<height):continue
            a=x+width*y;b=nx+width*ny;board=list(ids);board[a],board[b]=board[b],board[a]
            eligible=ids[a] in (1,2,3,4,5,6) and ids[b] in (1,2,3,4,5,6)
            if not eligible:blocked+=1
            expected.append('1' if eligible and matching_changed(board,{a,b}) else '0')
            matched=matching_cells(board) if eligible else set()
            boxes=set()
            for index in matched:
                mx,my=index%width,index//width
                for bx,by in ((mx-1,my),(mx+1,my),(mx,my-1),(mx,my+1)):
                    if 0<=bx<width and 0<=by<height and board[bx+by*width]==21:boxes.add(bx+by*width)
            box_counts.append(len(boxes))
            cases.append(f'{a},{b}#'+','.join(map(str,sorted(matched)))+'#'+','.join(map(str,sorted(boxes))))
